/* Controlled diagnostic only: completion waits are intentionally outside
 * allocation/upload call timers. SDL mali context matches the playable app. */
#include <SDL.h>
#include <GLES3/gl3.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <sys/resource.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"FAIL line=%d GL=%x SDL=%s\n",__LINE__,glGetError(),SDL_GetError());exit(2);}}while(0)
static double now(void){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec*1e-9;}
static GLuint shader(GLenum type,const char*s){GLuint q=glCreateShader(type);glShaderSource(q,1,&s,NULL);glCompileShader(q);GLint ok;glGetShaderiv(q,GL_COMPILE_STATUS,&ok);if(!ok){char log[4096];glGetShaderInfoLog(q,sizeof log,NULL,log);fprintf(stderr,"%s\n",log);}CHECK(ok);return q;}
static GLuint program(void){GLuint p=glCreateProgram();GLuint v=shader(GL_VERTEX_SHADER,"#version 300 es\nvoid main(){vec2 v=vec2((gl_VertexID<<1)&2,gl_VertexID&2);gl_Position=vec4(v*2.-1.,0,1);}");GLuint f=shader(GL_FRAGMENT_SHADER,"#version 300 es\nprecision highp float;uniform highp sampler2DArray tex;uniform float layer;out vec4 colour;void main(){colour=textureLod(tex,vec3(gl_FragCoord.xy/vec2(640,480),layer),0.);}");glAttachShader(p,v);glAttachShader(p,f);glLinkProgram(p);GLint ok;glGetProgramiv(p,GL_LINK_STATUS,&ok);CHECK(ok);glDeleteShader(v);glDeleteShader(f);return p;}
static void parameters(GLenum target){glTexParameteri(target,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(target,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(target,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(target,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);}
static GLuint allocate(int w,int h,int layers,int immutable,const void *payload){GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D_ARRAY,t);parameters(GL_TEXTURE_2D_ARRAY);if(immutable)glTexStorage3D(GL_TEXTURE_2D_ARRAY,1,GL_RGBA8,w,h,layers);else glTexImage3D(GL_TEXTURE_2D_ARRAY,0,GL_RGBA8,w,h,layers,0,GL_RGBA,GL_UNSIGNED_BYTE,NULL);for(int l=0;l<layers;l++)glTexSubImage3D(GL_TEXTURE_2D_ARRAY,0,0,0,l,w,h,1,GL_RGBA,GL_UNSIGNED_BYTE,payload);return t;}
static void draw(GLuint t,int layer,int loc){glBindTexture(GL_TEXTURE_2D_ARRAY,t);glUniform1f(loc,layer);for(int i=0;i<16;i++)glDrawArrays(GL_TRIANGLES,0,3);}
static int busy(GLsync fence){if(!fence)return -1;GLenum s=glClientWaitSync(fence,0,0);CHECK(s!=GL_WAIT_FAILED);return s==GL_TIMEOUT_EXPIRED;}
static const char *names[]={"A_fresh2d","B_fresh_mutable2","B_fresh_immutable2","C_persistent_idle2","D_same_completed","E_same_inflight","E_other_inflight","E_unrelated_inflight","F_orphan2","F_rotate3","F_persistent8","F_immutable_idle2","F_immutable_same_inflight"};
int main(int argc,char**argv){CHECK(argc==2);FILE*shape=fopen(argv[1],"r");CHECK(shape);CHECK(!SDL_Init(SDL_INIT_VIDEO));SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_ES);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,2);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,0);SDL_Window*window=SDL_CreateWindow("Mali texture diagnostic",0,0,640,480,SDL_WINDOW_OPENGL);CHECK(window&&SDL_GL_CreateContext(window));SDL_GL_SetSwapInterval(0);fprintf(stderr,"GL=%s renderer=%s vendor=%s\n",glGetString(GL_VERSION),glGetString(GL_RENDERER),glGetString(GL_VENDOR));GLint max;glGetIntegerv(GL_MAX_ARRAY_TEXTURE_LAYERS,&max);fprintf(stderr,"array_layers=%d\n",max);glUseProgram(program());GLint loc;/* query actual active program rather than assuming its name */GLint current;glGetIntegerv(GL_CURRENT_PROGRAM,&current);loc=glGetUniformLocation(current,"layer");glUniform1i(glGetUniformLocation(current,"tex"),0);glViewport(0,0,640,480);glDisable(GL_BLEND);glDisable(GL_DEPTH_TEST);
GLuint pressure[32];int pressure_n=0;const char *pressure_env=getenv("ENG_PROBE_PRESSURE_MIB");if(pressure_env){int mib=atoi(pressure_env);CHECK(mib>=0&&mib<=256);unsigned char *p=malloc(1024*1024*4);CHECK(p);for(int i=0;i<1024*1024*4;i++)p[i]=(unsigned char)(i*17);for(int i=0;i<mib;i+=8)pressure[pressure_n++]=allocate(1024,1024,2,0,p);free(p);glFinish();fprintf(stderr,"pressure_storage_mib=%d\n",pressure_n*8);}
puts("sample,case,w,h,layers,upload_bytes,storage_bytes,gen_us,bind_us,alloc_us,upload_us,delete_us,complete_us,busy_before,busy_after,maxrss_kib");int w,h;
while(fscanf(shape,"%d %d",&w,&h)==2){CHECK(w>0&&h>0&&w<=1025&&h<=1025);size_t bytes=(size_t)w*h*4;unsigned char *data=malloc(bytes);CHECK(data);uint32_t random=0x6d2b79f5;for(size_t i=0;i<bytes;i++){random^=random<<13;random^=random>>17;random^=random<<5;data[i]=(i%4==3)?255:random;}const char *payload_dir=getenv("ENG_PROBE_PAYLOAD_DIR");if(payload_dir){char path[1024];snprintf(path,sizeof path,"%s/%dx%d.rgba",payload_dir,w,h);FILE *p=fopen(path,"rb");CHECK(p&&fread(data,1,bytes,p)==bytes&&fgetc(p)==EOF);fclose(p);fprintf(stderr,"actual_payload=%dx%d bytes=%zu\n",w,h,bytes);}
GLuint persistent=allocate(w,h,2,0,data),orphan=allocate(w,h,2,0,data),imm=allocate(w,h,2,1,data),larger=allocate(w,h,8,0,data),unrelated=allocate(w,h,2,0,data),rotation[3];for(int i=0;i<3;i++)rotation[i]=allocate(w,h,2,0,data);glFinish();
for(int sample=-5;sample<40;sample++)for(int step=0;step<13;step++){int c=(step+sample+13)%13;GLuint t=persistent;GLenum target=c==0?GL_TEXTURE_2D:GL_TEXTURE_2D_ARRAY;int layers=c==0?1:c==10?8:2;double gen=0,bind=0,alloc=0,upload=0,deletion=0,completion=0,begin;GLsync fence=NULL;glFinish();if(c==4){draw(persistent,0,loc);glFinish();}if(c==5||c==6||c==7||c==8||c==9||c==12){GLuint read=c==8?orphan:c==7?unrelated:c==12?imm:c==9?rotation[(sample+6)%3]:persistent;draw(read,c==6?1:0,loc);fence=glFenceSync(GL_SYNC_GPU_COMMANDS_COMPLETE,0);glFlush();}int before=busy(fence);
if(c<=2){begin=now();glGenTextures(1,&t);gen=now()-begin;}else if(c==8)t=orphan;else if(c==9)t=rotation[(sample+7)%3];else if(c==10)t=larger;else if(c>=11)t=imm;
begin=now();glBindTexture(target,t);bind=now()-begin;if(c<=2)parameters(target);
if(c<=2||c==8){begin=now();if(c==0)glTexImage2D(target,0,GL_RGBA,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,NULL);else if(c==2)glTexStorage3D(target,1,GL_RGBA8,w,h,layers);else glTexImage3D(target,0,GL_RGBA8,w,h,layers,0,GL_RGBA,GL_UNSIGNED_BYTE,NULL);alloc=now()-begin;}
begin=now();if(c==0)glTexSubImage2D(target,0,0,0,w,h,GL_RGBA,GL_UNSIGNED_BYTE,data);else glTexSubImage3D(target,0,0,0,0,w,h,1,GL_RGBA,GL_UNSIGNED_BYTE,data);upload=now()-begin;int after=busy(fence);begin=now();glFinish();completion=now()-begin;if(fence)glDeleteSync(fence);if(c<=2){begin=now();glDeleteTextures(1,&t);deletion=now()-begin;}CHECK(glGetError()==GL_NO_ERROR);struct rusage r;getrusage(RUSAGE_SELF,&r);if(sample>=0)printf("%d,%s,%d,%d,%d,%zu,%zu,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%d,%d,%ld\n",sample,names[c],w,h,layers,bytes,bytes*layers,gen*1e6,bind*1e6,alloc*1e6,upload*1e6,deletion*1e6,completion*1e6,before,after,r.ru_maxrss);
}glDeleteTextures(1,&persistent);glDeleteTextures(1,&orphan);glDeleteTextures(1,&imm);glDeleteTextures(1,&larger);glDeleteTextures(1,&unrelated);glDeleteTextures(3,rotation);free(data);glFinish();}fclose(shape);glDeleteTextures(pressure_n,pressure);SDL_Quit();return 0;}
